def root_times_projection(value, observations=None):
    """Comparison only. Never change captured/live records or filesystem times.
    Routes are fixed generated metadata containers, not arbitrary app/env data.
    """
    if not isinstance(value, dict):
        return value
    out = dict(value)
    def record(r):
        need(isinstance(r, dict) and stat.S_ISDIR(r.get('statmode', 0))
             and r.get('kind', 'directory') == 'directory'
             and all(integer(r.get(k)) for k in ('mtimeNs', 'ctimeNs')),
             'ROOT_TIME_OBSERVATION_DIRECTORY_SCHEMA')
        if observations is not None:
            observations.append(dict(r))
        return {k:v for k,v in r.items() if k not in ('mtimeNs', 'ctimeNs')}
    if ROOT_TIME_OBSERVATION_PATH in out and isinstance(out[ROOT_TIME_OBSERVATION_PATH], dict):
        out[ROOT_TIME_OBSERVATION_PATH] = record(out[ROOT_TIME_OBSERVATION_PATH])
    if out.get('cwd') == ROOT_TIME_OBSERVATION_PATH and 'cwdMeta' in out:
        out['cwdMeta'] = record(out['cwdMeta'])
    # New 09:37:40 authorization: only path-keyed generated directory records.
    # Full actual records remain in capture/journal; compare necessary identity, not contentless directory size/times.
    for path, r in list(out.items()):
        if isinstance(path, str) and path.startswith('/') and path != ROOT_TIME_OBSERVATION_PATH and isinstance(r, dict) and r.get('kind') == 'directory':
            need(stat.S_ISDIR(r.get('statmode', 0)) and all(integer(r.get(k)) for k in ('dev','ino','statmode','uid','gid','nlink','size','mtimeNs','ctimeNs')), 'EXACT_DIRECTORY_OBSERVATION_SCHEMA')
            out[path] = {k:v for k,v in r.items() if k not in ('size','mtimeNs','ctimeNs')}
    for key in ('transport', 'externalProtection', 'protectedFiles', 'rootMeta', 'fullAdapterMeta'):
        if isinstance(out.get(key), dict):
            out[key] = root_times_projection(out[key], observations)
    if isinstance(out.get('processes'), list):
        out['processes'] = [root_times_projection(v, observations) for v in out['processes']]
    return out

def root_times_equal(actual, expected):
    observed = []
    same = root_times_projection(actual, observed) == root_times_projection(expected)
    if same and actual != expected:
        print(json.dumps(dict(observation='APPROVED_SINGLE_DIRECTORY_TIME_ONLY',
            observedAtUtc=now(), path=ROOT_TIME_OBSERVATION_PATH,
            comparedExcept=['mtimeNs','ctimeNs'], actualDirectoryRecords=observed),
            sort_keys=True), file=sys.stderr, flush=True)
