def exclusive(path, data, mode=0o600, uid=None, gid=None):
    check_locks()
    p = no_link(path)
    fd = os.open(p, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, mode)
