def adapter_files(cfg, entries):
    """Previously captured exact vendor closure paths, not per-step recursive package scanning."""
    roots = [cfg.pm2_base / 'modules' / n for n in ('pm2-axon', 'pm2-axon-rpc')]
    need(isinstance(entries, list) and entries == [str(p / 'index.js') for p in roots], 'EXACT_VENDORED_ADAPTER_ENTRIES')
    out = {}
    for value in SCOPE_POLICY['exactAdapterRecordPaths']:
        p = no_link(Path(value))
        need(any(p == root or root in p.parents for root in roots), 'ADAPTER_TREE_ESCAPE')
        r = describe(p)
        need(r['kind'] in ('file','directory'), 'ADAPTER_FILE_OR_DIRECTORY_ONLY')
        if r['kind'] == 'file': need(r['nlink'] == 1, 'ADAPTER_SINGLE_REGULAR_REQUIRED')
        out[str(p)] = r
    for root in roots:
        need(out.get(str(root), {}).get('kind') == 'directory' and out.get(str(root/'index.js'), {}).get('kind') == 'file', 'ADAPTER_INDEX_FILE_REQUIRED')
    return dict(sorted(out.items()))

